import type { Metadata } from "next";
import { siteConfig } from "./site";
import {
  defaultLocale,
  locales,
  localizedPath,
  type Locale,
} from "./i18n/config";

/**
 * The site-wide share card generated by `src/app/opengraph-image.tsx`. Kept as a
 * constant so pages that build their own `openGraph` block (posts with a cover)
 * have one obvious thing to fall back to.
 */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: siteConfig.title,
} as const;

/**
 * Build page metadata from the shared site defaults. `path` is the logical,
 * locale-agnostic path ("/blog"); `locale` decides the canonical URL.
 *
 * `hreflang` defaults to every locale the site publishes and narrows for paths
 * that only genuinely exist in some of them — an hreflang cluster claiming a
 * translation that isn't there is a worse signal than no cluster at all. The
 * site is currently English-only, so `locales` has one entry and no page emits a
 * `languages` block; the machinery stays because it is what a second locale
 * comes back through.
 *
 * `images` overrides the site-wide share card (pages with their own
 * `opengraph-image` route pass it here); `robots` is for pages that need to stay
 * reachable but out of the index.
 */
export function buildMetadata({
  title,
  description = siteConfig.description,
  path = "/",
  locale = defaultLocale,
  hreflang = locales,
  images = [DEFAULT_OG_IMAGE],
  robots,
}: {
  title?: string;
  description?: string;
  path?: string;
  locale?: Locale;
  hreflang?: readonly Locale[];
  images?: readonly { url: string; width: number; height: number; alt: string }[];
  robots?: Metadata["robots"];
}): Metadata {
  const canonical = localizedPath(locale, path);

  return {
    // Spread, not `title`: an explicit `title: undefined` key overrides the
    // layout's `title.default` instead of inheriting it, and the home page —
    // which passes no title — was shipping with no <title> element at all.
    ...(title !== undefined ? { title } : {}),
    description,
    ...(robots ? { robots } : {}),
    alternates: {
      canonical,
      ...(hreflang.length > 1
        ? {
            languages: {
              ...Object.fromEntries(
                hreflang.map((l) => [l, localizedPath(l, path)]),
              ),
              "x-default": localizedPath("en", path),
            },
          }
        : {}),
      // Each locale advertises its own feed, not the English one.
      types: {
        "application/rss+xml": localizedPath(locale, "/feed.xml"),
      },
    },
    openGraph: {
      title: title ? `${title} · ${siteConfig.name}` : siteConfig.title,
      description,
      url: canonical,
      siteName: siteConfig.name,
      locale: "en_US",
      type: "website",
      // Setting `openGraph` at all replaces the root segment's file-based card,
      // so it has to be named explicitly or every page built through here shares
      // with a blank preview. Relative — `metadataBase` (root layout) absolutises it.
      images: [...images],
    },
    twitter: {
      card: "summary_large_image",
      title: title ? `${title} · ${siteConfig.name}` : siteConfig.title,
      description,
      images: images.map((i) => i.url),
    },
  };
}
